local lpeg = require "lpeglabel"
local re = require "relabel"
local P, S, V, R, utfR = lpeg.P, lpeg.S, lpeg.V, lpeg.R, lpeg.utfR
  local EMPTY = P''
  local neg = function (pat)
   return P(1) - pat
  end
local regex = function (s)
	return re.compile(s)
end
local tk = function (s)
	return P(s) * V"SKIP_"^0
end
local EOF = P(-1)

  local ci =  function (s)
    local pat = P""
    for i = 1, #s do
      local ch = s:sub(i, i)
      local lower = ch:lower()
      local upper = ch:upper()
      if lower == upper then
       pat = pat * P(ch)
      else
       pat = pat * S(lower .. upper)
      end
    end
    return pat
  end

local grammar = {
	"start_",
    start_ = V"SKIP_"^0 *  V"acmeCompUnit",
	acmeCompUnit = (V"acmeImportDeclaration")^0 * (V"acmeSystemDeclaration" + V"acmeFamilyDeclaration" + V"acmeDesignDeclaration")^1 * V"EOF",
  acmeImportDeclaration = V"IMPORT" * (V"filename" + V"stringLiteral") * V"SEMICOLON",
  stringLiteral = V"STRING_LITERAL",
  filename = (tk(ci('$')) + tk(ci('%')))^-1 * V"IDENTIFIER" * ((tk(ci('.')) + tk(ci(':')) + tk(ci('-')) + tk(ci('+')) + tk(ci('\\')) + tk(ci('\\\\')) + tk(ci('/')) + tk(ci('$')) + tk(ci('%')))^1 * V"IDENTIFIER")^0,
  identifier = V"IDENTIFIER",
  codeLiteral = V"STRING_LITERAL",
  acmeFamilyDeclaration = (V"FAMILY" + V"STYLE") * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * V"acmeFamilyBody" * (V"SEMICOLON")^-1) + (V"EXTENDS" * V"acmeFamilyRef" * (V"COMMA" * V"acmeFamilyRef")^0 * (V"SEMICOLON" + (V"WITH" * V"acmeFamilyBody" * (V"SEMICOLON")^-1)))),
  acmeFamilyBody = V"LBRACE" * (((V"PUBLIC" + V"PRIVATE")^-1 * (V"FINAL" + V"ABSTRACT")^-1 * (V"acmePortTypeDeclaration" + V"acmeRoleTypeDeclaration" + V"acmeComponentTypeDeclaration" + V"acmeConnectorTypeDeclaration" + V"acmeGenericElementTypeDeclaration" + V"acmePropertyTypeDeclaration" + V"acmeGroupTypeDeclaration")) + V"acmeDesignAnalysisDeclaration" + V"designRule" + V"acmePortDeclaration" + V"acmeRoleDeclaration" + V"acmeComponentDeclaration" + V"acmeConnectorDeclaration" + V"acmePropertyDeclaration" + V"acmeGroupDeclaration" + V"acmeAttachmentDeclaration")^0 * V"RBRACE",
  acmeSystemDeclaration = V"SYSTEM" * V"identifier" * (V"COLON" * V"acmeFamilyRef" * (V"COMMA" * V"acmeFamilyRef")^0)^-1 * (V"SEMICOLON" + (V"ASSIGN" * ((V"acmeSystemBody" * (V"SEMICOLON")^-1) + (V"NEW" * V"acmeFamilyInstantiationRef" * (V"COMMA" * V"acmeFamilyInstantiationRef")^0 * (V"SEMICOLON" + (V"EXTENDED" * V"WITH" * V"acmeSystemBody" * (V"SEMICOLON")^-1)))))),
  acmeSystemBody = V"LBRACE" * (V"acmePropertyDeclaration" + V"acmeComponentDeclaration" + V"acmeConnectorDeclaration" + V"acmeAttachmentDeclaration" + V"acmeGroupDeclaration" + V"designRule")^0 * V"RBRACE",
  acmeDesignDeclaration = V"DESIGN",
  acmeComponentTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeComponentInstantiatedTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeConnectorTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeConnectorInstantiatedTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmePortTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmePortInstantiatedTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeGroupTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeGroupInstantiatedTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeRoleTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeRoleInstantiatedTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeViewTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeViewInstantiatedTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeFamilyRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeFamilyInstantiationRef = V"identifier",
  acmeElementTypeRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmePropertyTypeDeclarationRef = V"identifier" * (V"DOT" * V"identifier")^-1,
  acmeInstanceRef = V"IDENTIFIER" * (V"DOT" * V"IDENTIFIER")^0,
  acmeGenericElementTypeDeclaration = V"ELEMENT" * V"TYPE" * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * V"acmeGenericElementBody" * (V"SEMICOLON")^-1) + (V"EXTENDS" * V"acmeElementTypeRef" * (V"COMMA" * V"acmeElementTypeRef")^0 * (V"SEMICOLON" + (V"WITH" * V"acmeGenericElementBody" * (V"SEMICOLON")^-1)))),
  acmeGenericElementBody = V"LBRACE" * (V"acmePropertyDeclaration" + V"designRule")^0 * V"RBRACE",
  acmeGroupTypeDeclaration = V"GROUP" * V"TYPE" * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * V"acmeGroupBody" * (V"SEMICOLON")^-1) + (V"EXTENDS" * V"acmeGroupTypeRef" * (V"COMMA" * V"acmeGroupTypeRef")^0 * (V"SEMICOLON" + (V"WITH" * V"acmeGroupBody" * (V"SEMICOLON")^-1)))),
  acmeGroupDeclaration = V"GROUP" * V"identifier" * (V"COLON" * V"acmeGroupTypeRef" * (V"COMMA" * V"acmeGroupTypeRef")^0)^-1 * (V"SEMICOLON" + (V"ASSIGN" * ((V"acmeGroupBody" * (V"SEMICOLON")^-1) + (V"NEW" * V"acmeGroupInstantiatedTypeRef" * (V"COMMA" * V"acmeGroupInstantiatedTypeRef")^0 * (V"SEMICOLON" + (V"EXTENDED" * V"WITH" * V"acmeGroupBody" * (V"SEMICOLON")^-1)))))),
  acmeGroupBody = V"LBRACE" * (V"acmeMembersBlock" + V"acmePropertyDeclaration" + V"designRule")^0 * V"RBRACE",
  acmeMembersBlock = V"MEMBERS" * V"LBRACE" * (V"acmeInstanceRef" * (V"COMMA" * V"acmeInstanceRef")^0)^-1 * V"RBRACE" * V"FixedRepetition_0",
  acmePortTypeDeclaration = V"PORT" * V"TYPE" * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * V"acmePortBody" * (V"SEMICOLON")^-1) + (V"EXTENDS" * V"acmePortTypeRef" * (V"COMMA" * V"acmePortTypeRef")^0 * (V"SEMICOLON" + (V"WITH" * V"acmePortBody" * (V"SEMICOLON")^-1)))),
  acmePortDeclaration = V"PORT" * V"identifier" * (V"COLON" * V"acmePortTypeRef" * (V"COMMA" * V"acmePortTypeRef")^0)^-1 * ((V"ASSIGN" * ((V"acmePortBody" * (V"SEMICOLON")^-1) + (V"NEW" * V"acmePortInstantiatedTypeRef" * (V"COMMA" * V"acmePortInstantiatedTypeRef")^0 * (V"SEMICOLON" + (V"EXTENDED" * V"WITH" * V"acmePortBody" * (V"SEMICOLON")^-1))))) + (V"SEMICOLON")^-1),
  acmePortBody = V"LBRACE" * (V"acmePropertyDeclaration" + V"designRule" + V"acmeRepresentationDeclaration")^0 * V"RBRACE",
