  acmeRoleDeclaration = V"ROLE" * V"identifier" * (V"COLON" * V"acmeRoleTypeRef" * (V"COMMA" * V"acmeRoleTypeRef")^0)^-1 * (V"SEMICOLON" + (V"ASSIGN" * ((V"acmeRoleBody" * (V"SEMICOLON")^-1) + (V"NEW" * V"acmeRoleInstantiatedTypeRef" * (V"COMMA" * V"acmeRoleInstantiatedTypeRef")^0 * (V"SEMICOLON" + (V"EXTENDED" * V"WITH" * V"acmeRoleBody" * (V"SEMICOLON")^-1)))))),
  acmeRoleBody = V"LBRACE" * (V"acmePropertyDeclaration" + V"designRule" + V"acmeRepresentationDeclaration")^0 * V"RBRACE",
  acmeComponentTypeDeclaration = V"COMPONENT" * V"TYPE" * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * V"acmeComponentBody" * (V"SEMICOLON")^-1) + (V"EXTENDS" * V"acmeComponentTypeRef" * (V"COMMA" * V"acmeComponentTypeRef")^0 * (V"SEMICOLON" + (V"WITH" * V"acmeComponentBody" * (V"SEMICOLON")^-1)))),
  acmeComponentDeclaration = V"COMPONENT" * V"identifier" * (V"COLON" * V"acmeComponentTypeRef" * (V"COMMA" * V"acmeComponentTypeRef")^0)^-1 * (V"SEMICOLON" + (V"ASSIGN" * ((V"acmeComponentBody" * (V"SEMICOLON")^-1) + (V"NEW" * V"acmeComponentInstantiatedTypeRef" * (V"COMMA" * V"acmeComponentInstantiatedTypeRef")^0 * (V"SEMICOLON" + (V"EXTENDED" * V"WITH" * V"acmeComponentBody" * (V"SEMICOLON")^-1)))))),
  acmeComponentBody = V"LBRACE" * (V"acmePropertyDeclaration" + V"acmePortDeclaration" + V"designRule" + V"acmeRepresentationDeclaration")^0 * V"RBRACE",
  acmeConnectorTypeDeclaration = V"CONNECTOR" * V"TYPE" * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * V"acmeConnectorBody" * (V"SEMICOLON")^-1) + (V"EXTENDS" * V"acmeConnectorTypeRef" * (V"COMMA" * V"acmeConnectorTypeRef")^0 * (V"SEMICOLON" + (V"WITH" * V"acmeConnectorBody" * (V"SEMICOLON")^-1)))),
  acmeConnectorDeclaration = V"CONNECTOR" * V"identifier" * (V"COLON" * V"acmeConnectorTypeRef" * (V"COMMA" * V"acmeConnectorTypeRef")^0)^-1 * (V"SEMICOLON" + (V"ASSIGN" * ((V"acmeConnectorBody" * (V"SEMICOLON")^-1) + (V"NEW" * V"acmeConnectorInstantiatedTypeRef" * (V"COMMA" * V"acmeConnectorInstantiatedTypeRef")^0 * (V"SEMICOLON" + (V"EXTENDED" * V"WITH" * V"acmeConnectorBody" * (V"SEMICOLON")^-1)))))),
  acmeConnectorBody = V"LBRACE" * (V"acmePropertyDeclaration" + V"acmeRoleDeclaration" + V"designRule" + V"acmeRepresentationDeclaration")^0 * V"RBRACE",
  acmeRepresentationDeclaration = V"REPRESENTATION" * (V"IDENTIFIER" * V"ASSIGN")^-1 * V"LBRACE" * V"acmeSystemDeclaration" * (V"acmeBindingsMapDeclaration")^-1 * V"RBRACE" * V"FixedRepetition_1",
  acmeBindingsMapDeclaration = V"BINDINGS" * V"LBRACE" * (V"acmeBindingDeclaration")^0 * V"RBRACE" * (V"SEMICOLON")^-1,
