  acmePropertySet = V"LBRACE" * (V"acmePropertyValueDeclaration" * (V"COMMA" * V"acmePropertyValueDeclaration")^0)^-1 * V"RBRACE",
  acmePropertyRecordEntry = V"identifier" * (V"COLON" * V"acmePropertyTypeRef")^-1 * V"ASSIGN" * V"acmePropertyValueDeclaration",
  acmePropertyRecord = V"LBRACKET" * (V"acmePropertyRecordEntry" * (V"SEMICOLON" * V"acmePropertyRecordEntry")^0 * (V"SEMICOLON")^-1)^-1 * V"RBRACKET",
  acmePropertySequence = V"LANGLE" * (V"acmePropertyValueDeclaration" * (V"COMMA" * V"acmePropertyValueDeclaration")^0)^-1 * V"RANGLE",
  acmePropertyTypeRecord = V"RECORD" * V"LBRACKET" * (V"acmePropertyRecordFieldDescription")^0 * V"RBRACKET",
  acmePropertyTypeSet = V"SET" * V"LBRACE" * (V"acmeTypeRef")^-1 * V"RBRACE",
  acmePropertyTypeSequence = V"SEQUENCE" * V"LANGLE" * (V"acmePropertyTypeRef")^-1 * V"RANGLE",
  acmePropertyTypeEnum = V"ENUM" * V"LBRACE" * V"identifier" * (V"COMMA" * V"identifier")^0 * V"RBRACE",
  acmePropertyRecordFieldDescription = V"identifier" * V"COLON" * V"acmePropertyTypeRef" * V"SEMICOLON",
  acmePropertyTypeRef = V"acmePropertyTypeStructure" + V"acmePropertyTypeDeclarationRef",
  acmePropertyTypeStructure = V"acmePropertyTypeAny" + V"acmePropertyTypeInt" + V"acmePropertyTypeFloat" + V"acmePropertyTypeDouble" + V"acmePropertyTypeString" + V"acmePropertyTypeBoolean" + V"acmePropertyTypeRecord" + V"acmePropertyTypeSet" + V"acmePropertyTypeSequence" + V"acmePropertyTypeEnum",
  acmePropertyTypeDeclaration = V"PROPERTY" * V"TYPE" * V"identifier" * (V"SEMICOLON" + (V"ASSIGN" * (V"acmePropertyTypeInt" + V"acmePropertyTypeFloat" + V"acmePropertyTypeDouble" + V"acmePropertyTypeString" + V"acmePropertyTypeBoolean" + V"acmePropertyTypeRecord" + V"acmePropertyTypeSet" + V"acmePropertyTypeSequence" + V"acmePropertyTypeEnum" + V"acmePropertyTypeAny") * V"SEMICOLON")),
  acmePropertyBlockEntry = V"identifier" * (V"COLON" * V"acmePropertyTypeRef")^-1 * ((V"ASSIGN" * V"acmePropertyValueDeclaration") + (V"CONTAINASSIGN" * V"acmePropertyValueDeclaration"))^-1 * V"SEMICOLON",
