  acmeDesignAnalysisDeclaration = ((V"DESIGN")^-1 * V"ANALYSIS" * V"IDENTIFIER" * V"LPAREN" * (V"formalParam" * (V"COMMA" * V"formalParam")^0)^-1 * V"RPAREN" * V"COLON" * V"acmeTypeRef" * V"ASSIGN" * V"designRuleExpression" * (V"acmePropertyBlock")^-1 * V"SEMICOLON") + (V"EXTERNAL" * (V"DESIGN")^-1 * V"ANALYSIS" * V"IDENTIFIER" * V"LPAREN" * (V"formalParam" * (V"COMMA" * V"formalParam")^0)^-1 * V"RPAREN" * V"COLON" * V"acmeTypeRef" * V"ASSIGN" * (V"codeLiteral" + (V"identifier" * (V"DOT" * V"identifier")^0)) * V"SEMICOLON"),
