  pathExpressionContinuation = (V"setReference" * ((V"COLON" + V"SET_DECLARE") * V"acmeTypeRef")^-1 * (V"LBRACKET" * V"designRuleExpression" * V"RBRACKET")^-1 * (V"SLASH" * V"pathExpressionContinuation")^0) + ((V"ELLIPSIS")^-1 * V"reference"),
